import{_ as a,o as r,c as d,a3 as i}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"大学","description":"儒家四书之一：三纲领、八条目，为学与为政的总框架。","frontmatter":{"title":"大学","description":"儒家四书之一：三纲领、八条目，为学与为政的总框架。","category":"guide","aliases":["大学","大学章句","daxue","大学篇章","大学目录"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/daxue/index.md","filePath":"lizhimingde/sishu-wujing/daxue/index.md","lastUpdated":1790068742000}'),e={name:"lizhimingde/sishu-wujing/daxue/index.md"};function n(o,t,l,s,h,u){return r(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="大学" tabindex="-1">大学 <a class="header-anchor" href="#大学" aria-label="Permalink to &quot;大学&quot;">​</a></h1><p>《大学》原是《礼记》中的一篇，南宋朱熹把它抽出来单独成书，与《中庸》《论语》《孟子》合称四书。全文不长，却是四书里最像「大纲」的一部——它先把为学与为政的整张地图画出来。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>朱熹把《大学》分为「<strong>经一章</strong>」与「<strong>传十章</strong>」：</p><ul><li><strong>经一章</strong>：旧说为孔子之言、曾子述之，提出<strong>三纲领</strong>（明明德、亲民、止于至善）与<strong>八条目</strong>（格物、致知、诚意、正心、修身、齐家、治国、平天下）。</li><li><strong>传十章</strong>：旧说为曾子之意、门人记之，逐条解释经文——释明明德、释新民、释止于至善、释本末、释格物致知、释诚意、释正心修身、释修身齐家、释齐家治国、释治国平天下。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>它是儒家「由内到外」的完整路径图</strong>：从格物致知一路推到平天下，八条目一环扣一环。</li><li><strong>它把「修身」放在枢纽位置</strong>：「自天子以至于庶人，壹是皆以修身为本」——上下的功夫都从自己身上过。</li><li><strong>后世文章的常用语汇大量出自此篇</strong>：明明德、止于至善、格物致知、慎独、絜矩之道、日新又新。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读<strong>经一章</strong>，把三纲八目的框架记住——这是全篇的骨；</li><li>再读<strong>传十章</strong>，看每一章怎样逐条解释经文；</li><li>读时留意两个关键词：<strong>慎独</strong>（诚意章的功夫）与<strong>絜矩之道</strong>（治国章的尺度，即「己所不欲，勿施于人」的政治表达）；</li><li>「格物致知」一章朱熹补写过一段（原文此章有阙），读时可留意这一层版本问题。</li></ol><h2 id="篇章" tabindex="-1">篇章 <a class="header-anchor" href="#篇章" aria-label="Permalink to &quot;篇章&quot;">​</a></h2><p><strong>全篇一页承载</strong>：经一章 + 传十章，页内分十一节。</p><p>朱熹分《大学》为<strong>经一章</strong>、<strong>传十章</strong>：经是纲，传是目，传逐条解释经文。</p><h3 id="分节一览" tabindex="-1">分节一览 <a class="header-anchor" href="#分节一览" aria-label="Permalink to &quot;分节一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>节</th><th>内容</th><th>关键句</th></tr></thead><tbody><tr><td>一 · 经一章</td><td>三纲领八条目</td><td>大学之道，在明明德……</td></tr><tr><td>二 · 传·释诚意</td><td>毋自欺、慎独</td><td>故君子必慎其独也</td></tr><tr><td>三 · 传·释止于至善（一）</td><td>盛德至善</td><td>如切如磋，如琢如磨</td></tr><tr><td>四 · 传·释明明德</td><td>皆自明也</td><td>克明德 / 顾諟天之明命</td></tr><tr><td>五 · 传·释新民</td><td>苟日新</td><td>日日新，又日新</td></tr><tr><td>六 · 传·释止于至善（二）</td><td>各有所止</td><td>为人君，止于仁……</td></tr><tr><td>七 · 传·释本末</td><td>必也使无讼</td><td>听讼，吾犹人也</td></tr><tr><td>八 · 传·释正心修身</td><td>四者不得其正</td><td>心不在焉，视而不见</td></tr><tr><td>九 · 传·释修身齐家</td><td>五辟</td><td>人莫知其子之恶</td></tr><tr><td>十 · 传·释齐家治国</td><td>不出家而成教于国</td><td>一言偾事，一人定国</td></tr><tr><td>十一 · 传·释治国平天下</td><td>絜矩之道、以义为利</td><td>国不以利为利，以义为利也</td></tr></tbody></table><h3 id="阅读入口" tabindex="-1">阅读入口 <a class="header-anchor" href="#阅读入口" aria-label="Permalink to &quot;阅读入口&quot;">​</a></h3><ul><li><a href="/Dao/lizhimingde/sishu-wujing/daxue/chapter-01">《大学》全篇（一页承载）</a>——页内可用右侧目录在十一节间跳转</li></ul><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li>分节次序<strong>照所据底本的原文段落</strong>，不另按朱熹章次重排（朱熹本「诚意」章的位置与古本有异，此点读时留意）。</li><li>所引《诗》《书》原文依通行标点。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',20)])])}const m=a(e,[["render",n]]);export{c as __pageData,m as default};
